'use client'

import { useEffect, useSyncExternalStore } from 'react'

export type CategoryData = {
  slug: string
  heading: string
  products: string[]
}

type CachedCategory = {
  heading: string
  products: string[]
}

const cache = new Map<string, CachedCategory>()
const inflight = new Map<string, Promise<CachedCategory>>()
const listeners = new Set<() => void>()

function notify() {
  for (const listener of listeners) {
    listener()
  }
}

function subscribe(listener: () => void) {
  listeners.add(listener)
  return () => listeners.delete(listener)
}

function getSnapshot() {
  return cache
}

function getServerSnapshot() {
  return cache
}

export function seedCategoryCache(data: CategoryData[]) {
  for (const item of data) {
    cache.set(item.slug, {
      heading: item.heading,
      products: item.products,
    })
  }
  notify()
}

async function fetchCategory(slug: string): Promise<CachedCategory> {
  const response = await fetch(`/api/products?category=${encodeURIComponent(slug)}`)
  if (!response.ok) {
    throw new Error(`Failed to load category: ${slug}`)
  }

  const data = (await response.json()) as CachedCategory
  cache.set(slug, data)
  inflight.delete(slug)
  notify()
  return data
}

export function prefetchCategory(slug: string) {
  if (cache.has(slug) || inflight.has(slug)) {
    return
  }

  const promise = fetchCategory(slug)
  inflight.set(slug, promise)
  promise.catch(() => {
    inflight.delete(slug)
  })
}

export function getCategoryData(slug: string) {
  return cache.get(slug)
}

export function useCategoryData(slug: string) {
  const store = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)

  useEffect(() => {
    prefetchCategory(slug)
  }, [slug])

  return store.get(slug)
}

