import { CategoryLink } from '@/components/category-link'
import { CategoryPrefetch } from '@/components/category-prefetch'
import { categories, getProducts } from '@/lib/categories'

export async function CategoryLinks() {
  const categoryData = await Promise.all(
    categories.map(async (category) => ({
      slug: category.slug,
      heading: category.label,
      products: await getProducts(category.slug),
    }))
  )

  return (
    <>
      <CategoryPrefetch data={categoryData} />
      <ul>
        {categories.map((category) => (
          <li key={category.slug}>
            <CategoryLink slug={category.slug} label={category.label} />
          </li>
        ))}
      </ul>
    </>
  )
}

